"""Build an offline WebGL gallery from the actual C# ArenaMechanicRenderer vertex export.
Export: dotnet run --project tests/LocalizationChecks -c Release -- --export-mechanics /tmp/mechanics.json
"""
import argparse,base64,gzip,json
from pathlib import Path
ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('export',type=Path);ap.add_argument('--output',type=Path,required=True);args=ap.parse_args()
rows=json.loads(args.export.read_text());assert len(rows)==24
payload=base64.b64encode(gzip.compress(json.dumps(rows,ensure_ascii=False,separators=(',',':')).encode(),mtime=0)).decode()
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CCStats · 地图机制占位符</title>
<style>body{margin:0;background:#0b1220;color:#e4ecff;font:15px system-ui}main{max-width:1200px;margin:auto;padding:18px}h1{font-size:22px;margin:0 0 8px}p{line-height:1.6;color:#aabbd4}nav{display:flex;gap:6px;flex-wrap:wrap}button{border:1px solid #3d557e;border-radius:7px;background:#17253e;color:#dfeaff;padding:7px 10px;cursor:pointer}button.active{background:#286ca6;border-color:#6ccdf5;color:white}canvas{display:block;width:100%;height:520px;max-height:62vh;background:#080e18;border-radius:12px;margin-top:12px}#detail{min-height:65px}#title{margin:12px 0 0;font-size:19px}</style>
<main><h1>CCStats · 24 种地图机制占位符</h1><p>由插件实际 C# 渲染器导出。此页展示形状和动效，不代表对局事实、机关坐标或真实判定尺寸。左键旋转，滚轮缩放。</p><nav></nav><h2 id="title"></h2><canvas></canvas><p id="detail"></p></main><script>
(async()=>{const packed=Uint8Array.from(atob('PAYLOAD'),c=>c.charCodeAt(0));const items=JSON.parse(await new Response(new Blob([packed]).stream().pipeThrough(new DecompressionStream('gzip'))).text());
const canvas=document.querySelector('canvas'),gl=canvas.getContext('webgl2',{antialias:true,preserveDrawingBuffer:true});if(!gl)throw Error('WebGL2 不可用');
function shader(type,text){const s=gl.createShader(type);gl.shaderSource(s,text);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s}
const program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,'#version 300 es\\nin vec3 pos;in vec4 color;uniform mat4 matrix;out vec4 c;void main(){gl_Position=matrix*vec4(pos,1.);c=color;}'));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,'#version 300 es\\nprecision highp float;in vec4 c;out vec4 pixel;void main(){pixel=c;}'));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));gl.useProgram(program);
const buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);for(const [name,n,off]of [['pos',3,0],['color',4,12]]){const a=gl.getAttribLocation(program,name);gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,n,gl.FLOAT,false,28,off)}const uniform=gl.getUniformLocation(program,'matrix');gl.enable(gl.DEPTH_TEST);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);
const samples=items.map(item=>item.samples.map(v=>new Float32Array(v.flatMap(p=>[p[0],p[1],p[2],(p[3]&255)/255,((p[3]>>>8)&255)/255,((p[3]>>>16)&255)/255,(p[3]>>>24)/255]))));
const centers=items.map(item=>{const v=item.samples.flat(),lo=[0,1,2].map(i=>Math.min(...v.map(p=>p[i]))),hi=[0,1,2].map(i=>Math.max(...v.map(p=>p[i])));return {center:lo.map((x,i)=>(x+hi[i])/2),distance:Math.max(7,Math.max(...hi.map((x,i)=>x-lo[i]))*1.65)}});
let index=0,yaw=.5,pitch=.85,distance=centers[0].distance,lastFrame=-1,lastIndex=-1,drag=null;
function norm(v){const n=Math.hypot(...v);return v.map(x=>x/n)}function cross(a,b){return[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]}function dot(a,b){return a.reduce((s,x,i)=>s+x*b[i],0)}function multiply(a,b){let o=new Float32Array(16);for(let c=0;c<4;c++)for(let r=0;r<4;r++)for(let k=0;k<4;k++)o[c*4+r]+=a[k*4+r]*b[c*4+k];return o}
function draw(t=0){const frame=Math.floor(t/125)%8;const d=Math.min(devicePixelRatio||1,2);canvas.width=canvas.clientWidth*d;canvas.height=canvas.clientHeight*d;gl.viewport(0,0,canvas.width,canvas.height);
if(frame!==lastFrame||index!==lastIndex){gl.bufferData(gl.ARRAY_BUFFER,samples[index][frame],gl.DYNAMIC_DRAW);lastFrame=frame;lastIndex=index}
const center=centers[index].center,offset=[Math.sin(yaw)*Math.cos(pitch)*distance,Math.sin(pitch)*distance,Math.cos(yaw)*Math.cos(pitch)*distance],e=center.map((v,i)=>v+offset[i]),z=norm(offset),x=norm(cross([0,1,0],z)),y=cross(z,x),view=new Float32Array([x[0],y[0],z[0],0,x[1],y[1],z[1],0,x[2],y[2],z[2],0,-dot(x,e),-dot(y,e),-dot(z,e),1]);const f=1/Math.tan(.45),n=.1,far=2000,proj=new Float32Array([f/(canvas.width/canvas.height),0,0,0,0,f,0,0,0,0,(far+n)/(n-far),-1,0,0,2*far*n/(n-far),0]);gl.uniformMatrix4fv(uniform,false,multiply(proj,view));gl.clearColor(.031,.055,.094,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.drawArrays(gl.TRIANGLES,0,samples[index][frame].length/7);if(gl.getError())throw Error('GL render failed');}
const buttons=[];function select(i){index=i;distance=centers[i].distance;lastIndex=-1;document.querySelector('#title').textContent=items[i].name;document.querySelector('#detail').textContent=items[i].detail;buttons.forEach((b,j)=>b.classList.toggle('active',j===i));draw(0)}
items.forEach((item,i)=>{const b=document.createElement('button');b.textContent=item.name;b.onclick=()=>select(i);buttons.push(b);document.querySelector('nav').append(b)});
canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;yaw-=(e.clientX-drag[0])*.008;pitch=Math.max(.2,Math.min(1.5,pitch+(e.clientY-drag[1])*.008));drag=[e.clientX,e.clientY]};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;canvas.onwheel=e=>{e.preventDefault();distance=Math.max(3,Math.min(70,distance*Math.exp(e.deltaY*.001)))};
window.__select=select;window.__draw=draw;window.__items=items;select(0);function animate(t){draw(t);if(!window.__freeze)requestAnimationFrame(animate)}requestAnimationFrame(animate);window.__ready=true;
})().catch(e=>{window.__error=String(e);document.querySelector('#detail').textContent='加载失败：'+e})
</script></html>'''.replace('PAYLOAD',payload)
args.output.parent.mkdir(parents=True,exist_ok=True);args.output.write_text(html);print(args.output,len(html.encode()),'bytes')
